practice.starter:
const sentence = "the quick brown fox";
const numbers = "4:5:6";

// TODO: split the sentence into words and print the count, the words, the letters, and the reversed word

// TODO: split numbers on ":" and print the product

practice.solution:
const sentence = "the quick brown fox";
const numbers = "4:5:6";

const words = sentence.split(" ");
console.log(`Count: ${words.length}`);
console.log(`Words: ${words.join("-")}`);

const last = words.at(-1);
console.log(`Letters: ${last.split("").join(".")}`);
console.log(`Reversed: ${last.split("").reverse().join("")}`);

const parts = numbers.split(":");
let product = 1;
for (const part of parts) {
  product *= Number(part);
}
console.log(`Product: ${product}`);
